<?php
require __DIR__.'/../includes/bootstrap.php';require_admin($conn);$allowed=['pending','paid','processing','shipped','delivered','cancelled'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=post_string('status');if(in_array($status,$allowed,true)){$st=$conn->prepare("UPDATE orders SET status=? WHERE id=?");$st->bind_param('si',$status,$id);$st->execute();flash('success','Order status updated.');}redirect('admin/orders.php');}
$orders=$conn->query("SELECT o.id,o.total_amount,o.status,o.created_at,u.name,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC")->fetch_all(MYSQLI_ASSOC);$pageTitle='Manage orders';require __DIR__.'/../includes/header.php';?>
<section class="page-hero"><div class="container"><p class="eyebrow">ADMINISTRATION</p><h1>Manage <em>orders.</em></h1></div></section><section class="container section"><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Total</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['name'])?><small class="block"><?=e($o['email'])?></small></td><td><?=e(date('d M Y',strtotime($o['created_at'])))?></td><td><?=money($o['total_amount'])?></td><td><?=e(ucfirst($o['status']))?></td><td><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach($allowed as $s):?><option value="<?=$s?>" <?=$o['status']===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select><button class="text-link">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>
